(()=>{
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scenarios={
'高性能合成橡胶':{names:['硅填充橡胶界面分子动力学计算','配方多目标性能代理模型训练','64 组配方湿抓—耐磨批量预测','A/B 配方对照实验设计','配方实验数据异常与因子分析'],input:'配方—性能数据集 V3.1',models:['界面模拟服务','性能预测模型 V2.4','性能预测模型 V2.4','DMA / 磨耗试验','实验统计分析'],factors:[['白炭黑','55','75','phr'],['偶联剂','4','8','phr'],['硫化温度','145','165','℃']],headers:['样本','白炭黑 phr','偶联剂 phr','湿抓指数','磨耗 mm³','判定'],rows:[['R-01',55,4,1.08,105,'基线'],['R-02',65,6,1.16,96,'候选'],['R-03',75,8,1.21,102,'权衡'],['R-04',65,4,1.12,118,'异常待复核']],importance:[['白炭黑含量',42],['偶联剂比例',35],['硫化温度',23]],goal:'在湿抓、耐磨与滚阻约束下，验证配方性能权衡。'},
'页岩气储层评价':{names:['储层弹性参数敏感性计算','储层甜点识别代理模型训练','目标区块甜点候选批量预测','岩心物性对照实验设计','测井—岩心联合数据质量分析'],input:'目标区块测井解释数据 V3',models:['储层敏感性计算服务','储层多因素评价模型','储层多因素评价模型','岩心物性测试','地质数据统计分析'],factors:[['围压','10','30','MPa'],['孔隙度','3','9','%'],['含水饱和度','20','60','%']],headers:['岩样','围压 MPa','孔隙度 %','渗透率 mD','预测偏差 %','判定'],rows:[['C-01',10,3,0.08,4.2,'基线'],['C-02',20,6,0.15,3.5,'候选'],['C-03',30,9,0.21,5.1,'对照'],['C-04',20,6,0.03,18.4,'异常待复核']],importance:[['孔隙度',46],['围压',31],['含水饱和度',23]],goal:'识别储层关键控制因素并检验独立岩样上的稳定性。'},
'CO₂ 吸附材料筛选':{names:['候选吸附位点能量计算','吸附容量代理模型训练','候选结构吸附性能批量预测','温压条件吸附循环实验设计','吸附等温线拟合与异常分析'],input:'候选结构 V1 · 吸附等温线 V2',models:['吸附能计算服务','吸附性能预测模型 V0.8','吸附性能预测模型 V0.8','吸附分析仪','等温线拟合分析'],factors:[['温度','25','65','℃'],['压力','1','5','bar'],['循环次数','1','10','次']],headers:['材料','温度 ℃','压力 bar','容量 mmol/g','保持率 %','判定'],rows:[['M-01',25,1,2.4,96,'基线'],['M-02',45,3,3.8,94,'候选'],['M-03',65,5,4.1,90,'权衡'],['M-04',45,3,1.2,78,'异常待复核']],importance:[['压力',44],['温度',38],['循环次数',18]],goal:'比较吸附容量、循环保持率和再生条件的权衡。'}
};
const categories=['compute','training','inference','experiment','analysis'];
function seeds(scope,tasks){const s=scenarios[scope];if(!s)return[];return categories.map((k,i)=>{const t=tasks.find(t=>k==='experiment'?t[1].includes('做'):t[1].includes('算'))||tasks[0];return{id:`case-v1-${encodeURIComponent(scope)}-${k}`,scope,category:k,name:s.names[i],researchTask:t?.[0]||'',researchTitle:t?.[2]||'',purpose:s.goal,status:['运行中','已完成','已完成','待确认','已完成'][i],progress:i===0?68:i===3?0:100,input:s.input,model:s.models[i],modelVersion:'案例固定快照',software:s.models[i],params:k==='training'?{'训练轮次':120,'验证集比例':'20%','随机种子':42}:k==='experiment'?{'设计方法':'拉丁超立方','因子数':3,'批次样本数':8,'对照组':'基线 + 候选','重复次数':3}:k==='analysis'?{'分析方法':'质量检查 + 因子敏感性','异常策略':'标记后人工复核','评价口径':'同版本基线对照'}:{'方法':k==='compute'?'参数扫描':'批量预测','样本数':64,'随机种子':42},resource:k==='compute'?'计算队列 · 8 核 CPU（演示）':k==='experiment'?'实验室排程（演示）':'GPU 工作队列（演示）',owner:'林夏',created:'2026-10-02 · 案例演示',logs:['参考 PETROLAB 工作视图建立的合成案例；非真实科研结果'],output:i===0||i===3?'':`${k}-case-results.csv`,registered:false,caseStudy:true};});}
function table(headers,rows){return `<div class="exec-table-scroll"><table class="sc-table"><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${e(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function detail(r,tab){if(!r.caseStudy)return'';const s=scenarios[r.scope];if(!s)return'';const note='<p class="exec-case-note">合成案例数据，仅演示工作流程；不作为实际参数建议或科研结论。</p>';
if(r.category==='experiment'&&(tab==='配置与运行'||tab==='结果分析'))return `<section class="sc-card exec-card"><div class="exec-section-head"><h3>设计因子与水平</h3><span>3 因子 · 8 组组合 · 每组 3 次重复</span></div>${table(['因子','下限','上限','单位'],s.factors)}<div class="exec-section-head" style="margin-top:24px"><h3>实验设计矩阵</h3><button type="button" class="sc-btn" data-case-export>导出设计矩阵</button></div>${table(['试验编号',...s.factors.map(f=>f[0]+' '+f[3]),'角色','状态'],Array.from({length:8},(_,i)=>['DOE-'+String(i+1).padStart(2,'0'),...s.factors.map((f,j)=>i>>j&1?f[2]:f[1]),i===0?'基线对照':'候选组合','待排程']))}<p>设计方法：空间填充初始探索。复核因子边界、重复测量及设施条件后再排程。</p>${note}</section>`;
if(tab==='结果分析'&&['analysis','inference'].includes(r.category))return `<section class="sc-card exec-card"><div class="exec-section-head"><h3>样本结果与异常复核</h3><div><button type="button" class="sc-btn" data-case-filter="all">全部样本</button> <button type="button" class="sc-btn" data-case-filter="abnormal">仅异常</button> <button type="button" class="sc-btn" data-case-export>导出案例数据</button></div></div><div id="exec-case-results">${table(s.headers,s.rows)}</div>${note}</section><div class="exec-two-cols"><section class="sc-card exec-card"><h3>因子贡献 · 合成演示</h3>${s.importance.map(([n,v])=>`<div class="exec-importance"><span>${e(n)}</span><i><b style="width:${v}%"></b></i><strong>${v}%</strong></div>`).join('')}</section><section class="sc-card exec-card"><h3>分析判断与下一步</h3><p>异常样本应检查批次、仪器和输入条件；候选方案需与基线比较，避免单一指标替代多目标判断。</p><p>建议：复核异常 → 补充对照 → 更新模型或下一轮实验方案。该建议为案例流程说明。</p></section></div>`;
if(tab==='结果分析'&&r.category==='training')return `<section class="sc-card exec-card"><h3>训练评价快照 · 合成演示</h3>${table(['数据划分','相对 MAE（归一化）','R²','用途'],[['训练集',0.042,0.95,'拟合监测'],['验证集',0.067,0.89,'调参与选择'],['独立测试集',0.081,0.85,'泛化复核']])}${note}</section>`;return'';}
function bind(root,r){if(!r?.caseStudy)return;const s=scenarios[r.scope];root.querySelectorAll('[data-case-filter]').forEach(b=>b.onclick=()=>{root.querySelector('#exec-case-results').innerHTML=table(s.headers,b.dataset.caseFilter==='abnormal'?s.rows.filter(x=>x.at(-1).includes('异常')):s.rows);});root.querySelector('[data-case-export]')?.addEventListener('click',()=>{const matrix=r.category==='experiment',h=matrix?['编号',...s.factors.map(f=>f[0])]:s.headers,rows=matrix?Array.from({length:8},(_,i)=>['DOE-'+(i+1),...s.factors.map((f,j)=>i>>j&1?f[2]:f[1])]):s.rows;const url=URL.createObjectURL(new Blob(['\ufeff说明：合成演示数据\n'+[h,...rows].map(row=>row.join(',')).join('\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=matrix?'demo-design-matrix.csv':'demo-analysis-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
window.AI4SExecutionCases={seeds,detail,bind};
})();
